use std :: process :: Command ; use std :: env ; use std :: ffi :: OsString ; use std :: sync :: { LazyLock , Mutex , MutexGuard } ; use super :: * ; # [doc = " Attempts to install the Forge VS Code extension silently"] # [doc = ""] # [doc = " Returns Ok(true) if installation was successful, Ok(false) if it failed,"] # [doc = " or Err if the command couldn't be executed."] pub fn install_extension () -> Result < bool , std :: io :: Error > { let output = Command :: new ("code") . arg ("--install-extension") . arg ("ForgeCode.forge-vscode") . arg ("--force") . output () ? ; Ok (output . status . success ()) }